from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, in input order.

    Parities are computed in parallel with a thread pool. The result order
    matches the input order and does not depend on the number of workers.
    Negative numbers map to 0 or 1 (e.g. -3 -> 1). The input is not modified.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4, 5]) == [0, 1, 0, 1, 0, 1]


def test_parities_negative() -> None:
    assert parities([-1, -2, -3, -4]) == [1, 0, 1, 0]


def test_parities_single() -> None:
    assert parities([7]) == [1]
    assert parities([8]) == [0]


def test_parities_preserves_order_large() -> None:
    xs = [(i * 7919) % 1000 - 500 for i in range(5000)]
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_order_not_sorted_by_value() -> None:
    xs = [3, 2, 2, 3, 1, 0, 0, 1]
    assert parities(xs) == [1, 0, 0, 1, 1, 0, 0, 1]


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 4, 3]
    copy = list(xs)
    parities(xs)
    assert xs == copy


def test_parities_big_ints() -> None:
    assert parities([2**100, 2**100 + 1, -(2**100) - 1]) == [0, 1, 1]
